function money(value:string|null|undefined){if(value==null)return "—";return `$${Number(value).toLocaleString("tr-TR",{maximumFractionDigits:4})}`}
function numeric(value:string|null|undefined){if(value==null||value==="")return null;const parsed=Number(value);return Number.isFinite(parsed)?parsed:null}
function compact(value:number){if(value>=1_000_000)return `${(value/1_000_000).toLocaleString("tr-TR",{maximumFractionDigits:1})}M`;if(value>=1000)return `${(value/1000).toLocaleString("tr-TR",{maximumFractionDigits:1})}K`;return value.toLocaleString("tr-TR")}
function trModality(tag:string){
  const map:Record<string,string>={text:"metin",image:"gorsel",audio:"ses",video:"video"};
  return map[tag.toLowerCase()]??tag;
}
function trCapability(tag:string){return capabilityLabels[tag.toLowerCase()]??tag}
function daysAgoIso(days:number){const d=new Date();d.setDate(d.getDate()-days);return d.toISOString()}
function canOpenSourceUrl(url:string|null|undefined){
  if(!url)return false;
  const value=url.toLowerCase();
  if(!value.startsWith("http://")&&!value.startsWith("https://"))return false;
  if(value.includes("datasets-server.huggingface.co/rows"))return false;
  if(value.includes("/api/"))return false;
  if(value.includes("/api/v1/models"))return false;
  if(value.endsWith(".json")||value.endsWith(".jsonl")||value.endsWith(".csv"))return false;
  return true;
}
