function sourceBadge(license:string|null|undefined){
  const normalized=(license??"").trim().toLowerCase();
  if(!normalized||normalized==="unknown"||normalized==="n/a")return {label:"?",description:"Kaynak durumu bilinmiyor",kind:"unknown"};
  if(normalized.includes("proprietary")||normalized.includes("closed source")||normalized.includes("closed-source"))return {label:"Closed",description:"Closed-source",kind:"closed"};
  return {label:"Open",description:"Open-source",kind:"open"};
}
